entries[6363] = { ["name"] = "Totem der Verbrennung", ["text"] = "45 Mana\nSofort\nTools: Feuertotem\nBeschwört 35 Sek. lang ein Totem der Verbrennung mit 5 Punkt(en) Gesundheit zu Euren Füßen, das alle 2 Sekunden einen Feind im Umkreis von 20 Metern angreift und 13 bis 17 Punkt(e) Feuerschaden anrichtet." }
